import{_ as t,o as e,c as i,a as o}from"./app.DkoUFz-u.js";const p=JSON.parse('{"title":"数据库层开发-高性能访问-数据分片-Citus分布式PostgreSQL","description":"","frontmatter":{},"headers":[],"relativePath":"data/performance/sharding/tools/citus.md","filePath":"data/performance/sharding/tools/citus.md"}'),r={name:"data/performance/sharding/tools/citus.md"};function l(s,a,n,h,d,u){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="数据库层开发-高性能访问-数据分片-citus分布式postgresql" tabindex="-1">数据库层开发-高性能访问-数据分片-Citus分布式PostgreSQL <a class="header-anchor" href="#数据库层开发-高性能访问-数据分片-citus分布式postgresql" aria-label="Permalink to &quot;数据库层开发-高性能访问-数据分片-Citus分布式PostgreSQL&quot;">​</a></h1><h2 id="一、citus概述" tabindex="-1">一、Citus概述 <a class="header-anchor" href="#一、citus概述" aria-label="Permalink to &quot;一、Citus概述&quot;">​</a></h2><h3 id="_1-1-什么是citus" tabindex="-1">1.1 什么是Citus <a class="header-anchor" href="#_1-1-什么是citus" aria-label="Permalink to &quot;1.1 什么是Citus&quot;">​</a></h3><p>Citus是一个开源的PostgreSQL扩展，它将Postgres转变为分布式数据库，使单台PostgreSQL服务器能够横向扩展为分布式集群。Citus允许普通的数据库服务器（称为节点）在“无共享（Shared-Nothing）”架构中相互协调。节点共同组成一个集群，使PostgreSQL能够存储比单台计算机更多的数据并使用更多的CPU核心。</p><p>Citus作为PostgreSQL扩展，通过钩子和扩展API提供分布式功能，用户可以受益于丰富的PostgreSQL生态系统所带来的特性——包括广泛的数据类型（如jsonb和hstore）、操作符和函数、全文搜索，以及PostGIS、HyperLogLog等其他扩展。同时，Citus兼容标准的PostgreSQL工具，如pgAdmin、pg_backup和pg_upgrade。</p><h3 id="_1-2-citus的设计理念" tabindex="-1">1.2 Citus的设计理念 <a class="header-anchor" href="#_1-2-citus的设计理念" aria-label="Permalink to &quot;1.2 Citus的设计理念&quot;">​</a></h3><p>Citus的设计遵循以下核心理念：</p><ul><li><strong>透明分片</strong>：通过扩展PostgreSQL的钩子和API，Citus使分布式行为对应用透明</li><li><strong>无共享架构</strong>：每个节点拥有独立的CPU、内存和存储资源，避免资源争用</li><li><strong>线性扩展</strong>：当工作数据集适配内存时，Citus的性能提升与工作节点核心数成正比</li><li><strong>标准SQL支持</strong>：使用标准PostgreSQL SQL结构，对于访问单个节点的查询提供完整的SQL支持</li></ul><h3 id="_1-3-核心应用场景" tabindex="-1">1.3 核心应用场景 <a class="header-anchor" href="#_1-3-核心应用场景" aria-label="Permalink to &quot;1.3 核心应用场景&quot;">​</a></h3><p>Citus主要面向两类典型场景：</p><p><strong>多租户SaaS应用</strong>：采用分层数据库建模，通过租户ID在分布式集群中分配查询。数据层次结构的顶部称为“租户ID”，需要存储在每个表的列中。Citus检查查询以确定涉及的租户ID，然后将查询路由到单个工作节点进行处理。</p><p><strong>实时分析应用</strong>：依赖于数据的特定分布属性来实现高度并行处理。使用“实体ID”（如用户、主机或设备）作为分布列，将查询发送到每个分片获取部分结果，在协调节点上组装最终答案。</p><h2 id="二、核心架构" tabindex="-1">二、核心架构 <a class="header-anchor" href="#二、核心架构" aria-label="Permalink to &quot;二、核心架构&quot;">​</a></h2><h3 id="_2-1-节点类型" tabindex="-1">2.1 节点类型 <a class="header-anchor" href="#_2-1-节点类型" aria-label="Permalink to &quot;2.1 节点类型&quot;">​</a></h3><p>Citus集群包含两种核心节点：</p><p><strong>协调节点（Coordinator）</strong> ：集群中的特殊节点，应用将查询发送到协调节点，它负责将查询中继到相关的工作节点并汇总结果。协调节点通过查询其元数据表来决定将查询路由到单个工作节点还是在多个节点间并行化。协调节点本身是一个安装了Citus扩展的标准PostgreSQL数据库。</p><p><strong>工作节点（Worker）</strong> ：集群中除协调节点外的其他节点。它们存储实际的数据分片，执行分配到的查询片段。每个工作节点本质上是一个标准的PostgreSQL实例。</p><h3 id="_2-2-无共享架构" tabindex="-1">2.2 无共享架构 <a class="header-anchor" href="#_2-2-无共享架构" aria-label="Permalink to &quot;2.2 无共享架构&quot;">​</a></h3><p>Citus采用无共享（Shared-Nothing）架构，每个节点拥有独立的CPU、内存和存储资源。这种架构允许数据库通过向集群添加更多节点来实现扩展。Citus的逻辑分片架构还允许随时添加新的工作节点，以增加集群的容量和处理能力。</p><h3 id="_2-3-元数据表" tabindex="-1">2.3 元数据表 <a class="header-anchor" href="#_2-3-元数据表" aria-label="Permalink to &quot;2.3 元数据表&quot;">​</a></h3><p>协调节点维护元数据表，用于跟踪所有工作节点的DNS名称和健康状态，以及数据在节点间的分布情况。这些元数据表还维护分片的大小和最小/最大值等统计信息，帮助Citus的分布式查询优化器优化传入查询。元数据表通常很小（仅几MB），如果协调节点发生故障，可以复制并快速恢复。</p><h3 id="_2-4-mx模式-citus-11-0" tabindex="-1">2.4 MX模式（Citus 11.0+） <a class="header-anchor" href="#_2-4-mx模式-citus-11-0" aria-label="Permalink to &quot;2.4 MX模式（Citus 11.0+）&quot;">​</a></h3><p>在Citus早期版本中，协调器是客户端查询的唯一入口。从Citus 11开始，客户端也可以直接连接到任何工作节点并提交查询，这称为MX模式。MX模式解决了两个扩展问题：</p><ul><li><strong>协调器热点</strong>：当所有客户端都连接到一个节点时，该节点的连接槽、CPU和网络会成为瓶颈。允许工作节点接受客户端连接，将负载分散到整个集群</li><li><strong>分片本地查询的延迟</strong>：当客户端连接到已存储相关分片的工作节点时，Citus可以规划并执行对本地分片表的查询，无需额外网络跳数</li></ul><h2 id="三、表类型与数据分布" tabindex="-1">三、表类型与数据分布 <a class="header-anchor" href="#三、表类型与数据分布" aria-label="Permalink to &quot;三、表类型与数据分布&quot;">​</a></h2><p>Citus集群中存在三种类型的表，每种用于不同目的。</p><h3 id="_3-1-分布式表-distributed-tables" tabindex="-1">3.1 分布式表（Distributed Tables） <a class="header-anchor" href="#_3-1-分布式表-distributed-tables" aria-label="Permalink to &quot;3.1 分布式表（Distributed Tables）&quot;">​</a></h3><p>分布式表是最常见、最主要的表类型。它们对SQL语句表现为普通表，但在工作节点上进行了水平分区。</p><p><strong>分片（Shard）</strong> ：分布式表的行存储在工作节点上的多个物理表中，这些组件表称为分片。每个分片实际上是一个PostgreSQL表。Citus不仅运行SQL语句，还运行整个集群的DDL语句，因此更改分布式表的模式会级联更新所有工作节点上的所有分片。</p><p><strong>分布列（Distribution Column）</strong> ：Citus使用算法分片（Algorithmic Sharding）将行分配给分片。分配是确定性的——基于特定表列（称为分布列）的值。集群管理员在分布表时必须指定此列，正确的选择对性能和功能至关重要。</p><h3 id="_3-2-引用表-reference-tables" tabindex="-1">3.2 引用表（Reference Tables） <a class="header-anchor" href="#_3-2-引用表-reference-tables" aria-label="Permalink to &quot;3.2 引用表（Reference Tables）&quot;">​</a></h3><p>引用表是一种特殊的分布式表，其全部内容集中到单个分片中，并在每个工作节点上复制。因此，任何工作节点上的查询都可以在本地访问引用信息，无需从另一个节点请求行的网络开销。</p><p>引用表没有分布列，因为不需要按行区分单独的分片。引用表通常很小，用于存储与任何工作节点上运行的查询相关的数据，如枚举值（订单状态、产品类别）。与引用表交互时，Citus自动执行两阶段提交（2PC）以确保数据一致性。</p><h3 id="_3-3-本地表-local-tables" tabindex="-1">3.3 本地表（Local Tables） <a class="header-anchor" href="#_3-3-本地表-local-tables" aria-label="Permalink to &quot;3.3 本地表（Local Tables）&quot;">​</a></h3><p>当使用Citus时，连接的协调节点是一个安装了Citus扩展的常规PostgreSQL数据库。因此，可以创建普通表并选择不分片它们。这对于不参与连接查询的小型管理表很有用，例如用于应用程序登录和认证的用户表。</p><h2 id="四、分布列的选择" tabindex="-1">四、分布列的选择 <a class="header-anchor" href="#四、分布列的选择" aria-label="Permalink to &quot;四、分布列的选择&quot;">​</a></h2><h3 id="_4-1-分布列的重要性" tabindex="-1">4.1 分布列的重要性 <a class="header-anchor" href="#_4-1-分布列的重要性" aria-label="Permalink to &quot;4.1 分布列的重要性&quot;">​</a></h3><p>为每个表选择分布列是最重要的建模决策之一，因为它决定了数据如何在节点间分布。如果正确选择分布列，相关数据将在同一物理节点上完成连接，使查询快速并支持所有SQL功能。如果选择不正确，系统将运行缓慢，并且无法跨节点支持所有SQL功能。</p><h3 id="_4-2-选择原则" tabindex="-1">4.2 选择原则 <a class="header-anchor" href="#_4-2-选择原则" aria-label="Permalink to &quot;4.2 选择原则&quot;">​</a></h3><p>通常情况下，应选择最常用的连接键或大多数查询具有过滤器的列作为分布列。</p><p><strong>对于过滤器</strong>：Citus使用分布列范围来修剪无关的分片，确保查询只命中与WHERE子句范围重叠的分片。</p><p><strong>对于连接</strong>：如果连接键与分布列相同，Citus只在具有匹配/重叠分布列范围的分片之间执行连接，大大减少每个节点的计算量和跨节点传输分片的网络带宽。</p><h3 id="_4-3-多租户场景的最佳实践" tabindex="-1">4.3 多租户场景的最佳实践 <a class="header-anchor" href="#_4-3-多租户场景的最佳实践" aria-label="Permalink to &quot;4.3 多租户场景的最佳实践&quot;">​</a></h3><p>在多租户模型中：</p><ul><li>通过共享的<code>tenant_id</code>列对分布式表进行分区。例如，在租户是公司的SaaS应用中，<code>tenant_id</code>可能是<code>company_id</code></li><li>将小型跨租户表转换为引用表</li><li>按<code>tenant_id</code>限制筛选所有应用程序查询，每次查询只请求一个租户的信息</li></ul><h3 id="_4-4-实时分析场景的最佳实践" tabindex="-1">4.4 实时分析场景的最佳实践 <a class="header-anchor" href="#_4-4-实时分析场景的最佳实践" aria-label="Permalink to &quot;4.4 实时分析场景的最佳实践&quot;">​</a></h3><p>在实时分析模型中：</p><ul><li>选择具有<strong>高基数</strong>的列作为分布列。例如，订单表中的“状态”字段（值为“new”、“paid”、“shipped”）是糟糕的选择，因为只有三个不同值，限制了可保存数据的分片数和可处理它的节点数</li><li>选择<strong>均匀分布</strong>的列。如果根据偏向特定公用值的列进行分布，数据会累积到特定分片，导致这些节点执行更多工作</li></ul><h3 id="_4-5-分布方法" tabindex="-1">4.5 分布方法 <a class="header-anchor" href="#_4-5-分布方法" aria-label="Permalink to &quot;4.5 分布方法&quot;">​</a></h3><p>Citus支持两种分片策略：</p><ul><li><strong>哈希分片</strong>：通过<code>DISTRIBUTE BY HASH(column)</code>指定，确保相同键值的记录落在同一分片，适合等值查询场景</li><li><strong>范围分片</strong>：使用<code>DISTRIBUTE BY RANGE(column)</code>，按数值或日期范围划分，优化范围查询性能</li></ul><h2 id="五、查询处理" tabindex="-1">五、查询处理 <a class="header-anchor" href="#五、查询处理" aria-label="Permalink to &quot;五、查询处理&quot;">​</a></h2><h3 id="_5-1-查询处理架构" tabindex="-1">5.1 查询处理架构 <a class="header-anchor" href="#_5-1-查询处理架构" aria-label="Permalink to &quot;5.1 查询处理架构&quot;">​</a></h3><p>Citus的查询处理流程包含两个核心组件：</p><ul><li><strong>分布式查询规划器与执行器</strong></li><li><strong>PostgreSQL规划器与执行器</strong></li></ul><p>当一个查询被提交到集群时，协调节点将查询划分为更小的查询片段，每个查询片段可以在一个分片上独立运行。协调节点然后将查询片段分配给工作节点，监督其执行，合并结果，并将最终结果返回给用户。</p><h3 id="_5-2-分布式查询规划器" tabindex="-1">5.2 分布式查询规划器 <a class="header-anchor" href="#_5-2-分布式查询规划器" aria-label="Permalink to &quot;5.2 分布式查询规划器&quot;">​</a></h3><p>Citus的分布式查询规划器接收SQL查询并规划分布式执行。对于SELECT查询，规划器首先创建输入查询的计划树，并将其转换为可交换和关联形式以便并行化。同时应用多项优化，确保查询以可扩展方式执行并最小化网络I/O。</p><p>接下来，规划器将查询分为两部分：</p><ul><li><strong>协调器查询</strong>：在协调节点上运行</li><li><strong>工作器查询片段</strong>：在工作节点上的各个分片上运行</li></ul><p>规划器然后将这些查询片段分配给工作节点，确保所有资源得到有效利用。</p><p>对于分布列上的键值查找或修改查询，规划过程略有不同——它们只命中一个分片。规划器提取传入行中的分布列，查询元数据以确定正确的分片，然后将SQL重写为引用分片表而非原始表。</p><h3 id="_5-3-分布式查询执行器" tabindex="-1">5.3 分布式查询执行器 <a class="header-anchor" href="#_5-3-分布式查询执行器" aria-label="Permalink to &quot;5.3 分布式查询执行器&quot;">​</a></h3><p>Citus的分布式执行器运行分布式查询计划并处理故障。执行器按需为每个分片打开一个到工作节点的连接，发送所有片段查询，获取每个片段查询的结果，合并后返回给用户。</p><p>Citus有两种执行器类型：</p><ul><li><strong>自适应执行器</strong>：用于大多数查询</li><li><strong>任务跟踪执行器</strong>：用于重分区连接等场景</li></ul><p>Citus根据每个查询的结构动态选择使用哪种执行器，甚至可以对单个查询的不同子查询/CTE使用不同的执行器。</p><h3 id="_5-4-故障处理" tabindex="-1">5.4 故障处理 <a class="header-anchor" href="#_5-4-故障处理" aria-label="Permalink to &quot;5.4 故障处理&quot;">​</a></h3><p>如果执行器无法将任务分配给指定的工作节点，或任务执行失败，执行器会动态地将任务重新分配给其他工作节点上的副本。处理故障时，执行器只重新处理失败的查询子树，而非整个查询。</p><p>Citus由于其基于逻辑分片的架构，能够轻松容忍工作节点故障。如果工作节点在查询中途失败，Citus通过将查询的失败部分重新路由到拥有分片副本的其他工作节点来完成查询。</p><h2 id="六、集群管理" tabindex="-1">六、集群管理 <a class="header-anchor" href="#六、集群管理" aria-label="Permalink to &quot;六、集群管理&quot;">​</a></h2><h3 id="_6-1-分片数量选择" tabindex="-1">6.1 分片数量选择 <a class="header-anchor" href="#_6-1-分片数量选择" aria-label="Permalink to &quot;6.1 分片数量选择&quot;">​</a></h3><p>为每个分布式表选择分片数量需要在拥有更多分片的灵活性与跨分片查询规划和执行的开销之间取得平衡。</p><p><strong>多租户SaaS场景</strong>：</p><ul><li>对于较小的工作负载（小于100GB），从32个分片开始</li><li>对于较大的工作负载，选择64或128个分片</li><li>这为从32到128个工作机器的扩展提供了余地</li></ul><p><strong>实时分析场景</strong>：</p><ul><li>分片数量应与工作节点上的总核心数相关</li><li>在每个节点上创建足够的分片，使每个CPU核心至少有一个分片</li><li>通常创建初始分片数量的2倍或4倍，为未来扩展留出空间</li><li>注意：每个查询Citus为每个分片打开一个数据库连接，连接数有限，需确保<code>（最大并发查询数 × 分片数）</code>不超过系统总连接数<code>（工作节点数 × max_connections）</code></li></ul><h3 id="_6-2-分片再平衡" tabindex="-1">6.2 分片再平衡 <a class="header-anchor" href="#_6-2-分片再平衡" aria-label="Permalink to &quot;6.2 分片再平衡&quot;">​</a></h3><p>Citus Community Edition 11.0+支持完全在线的分片再平衡，使分片在节点间移动或在故障节点上重新复制分片变得更容易。</p><p>使用<code>citus_rebalance_start</code>函数可以将现有分片移到新添加的工作器，该函数将分片均匀地分配给工作器。再平衡操作可以配置为并行执行多个分片移动，以牺牲更多资源（如网络带宽）来换取更快的平衡。</p><p>Citus 13.2显著改进了分片再平衡性能，通过增强的并行化和优化的锁策略解决了以前限制再平衡速度的关键瓶颈，特别是对于具有大引用表和多个共置分片的集群。</p><h3 id="_6-3-节点管理" tabindex="-1">6.3 节点管理 <a class="header-anchor" href="#_6-3-节点管理" aria-label="Permalink to &quot;6.3 节点管理&quot;">​</a></h3><p>当向Citus集群添加更多节点以提高查询性能和可扩展性时，Citus的逻辑分片架构允许无缝扩展。在加载数据时，可以指定复制因子以提供所需的数据可用性。面对工作节点故障，Citus自动切换到这些副本以服务查询。</p><h2 id="七、共置-colocation" tabindex="-1">七、共置（Colocation） <a class="header-anchor" href="#七、共置-colocation" aria-label="Permalink to &quot;七、共置（Colocation）&quot;">​</a></h2><h3 id="_7-1-什么是共置" tabindex="-1">7.1 什么是共置 <a class="header-anchor" href="#_7-1-什么是共置" aria-label="Permalink to &quot;7.1 什么是共置&quot;">​</a></h3><p>共置是指将相关数据放在同一节点上的技术。在多租户数据模型中，当两个表都限制为相同的<code>account_id</code>时，它们之间的连接查询可以将所有必要的数据包含在同一个节点上。</p><p>对于关联查询频繁的表（如订单与订单明细），通过使用相同的分布列创建表来实现共置分片。Citus可以在单个PostgreSQL节点上回答原本相同的查询而无需修改。</p><h3 id="_7-2-共置带来的功能支持" tabindex="-1">7.2 共置带来的功能支持 <a class="header-anchor" href="#_7-2-共置带来的功能支持" aria-label="Permalink to &quot;7.2 共置带来的功能支持&quot;">​</a></h3><p>通过共置启用的Citus功能完整列表包括：</p><ul><li>为单个共置分片的查询提供完整的SQL支持</li><li>多语句事务支持对单个共置分片集进行修改</li><li>聚合方式<code>INSERT..SELECT</code></li><li>外键</li><li>分布式外部连接</li><li>下推CTE（需要PostgreSQL &gt;=12）</li></ul><p>数据共置是一种强大的技术，用于为关系数据模型提供水平扩展和支持。使用通过共置实现关系操作的分布式数据库迁移或生成应用程序的成本，通常远低于迁移到限制性数据模型（如NoSQL）。</p><h2 id="八、性能调优" tabindex="-1">八、性能调优 <a class="header-anchor" href="#八、性能调优" aria-label="Permalink to &quot;八、性能调优&quot;">​</a></h2><h3 id="_8-1-调优思路" tabindex="-1">8.1 调优思路 <a class="header-anchor" href="#_8-1-调优思路" aria-label="Permalink to &quot;8.1 调优思路&quot;">​</a></h3><p>调优Citus集群以获得最大性能的第一步是调优工作节点上的PostgreSQL配置参数。参数调优是一个需要实验的过程，通常需要多次尝试才能达到可接受的性能。</p><h3 id="_8-2-使用explain分析" tabindex="-1">8.2 使用EXPLAIN分析 <a class="header-anchor" href="#_8-2-使用explain分析" aria-label="Permalink to &quot;8.2 使用EXPLAIN分析&quot;">​</a></h3><p>从协调节点对代表性查询运行<code>EXPLAIN</code>命令以检查性能。Citus扩展了<code>EXPLAIN</code>命令以提供分布式查询执行的信息。使用<code>VERBOSE</code>标志可以看到发送到工作节点的实际查询。</p><p><code>EXPLAIN</code>输出显示每个工作节点如何处理查询，以及协调节点如何组合它们的结果。</p><h3 id="_8-3-硬件规划" tabindex="-1">8.3 硬件规划 <a class="header-anchor" href="#_8-3-硬件规划" aria-label="Permalink to &quot;8.3 硬件规划&quot;">​</a></h3><p><strong>初始硬件大小</strong>：</p><ul><li>从现有单节点数据库迁移到Citus时，选择工作节点核心数和RAM总量与原始实例匹配的集群</li><li>在这种场景下，由于分片改善了资源利用率（允许使用更小的索引等），可以看到2-3倍的性能提升</li><li>协调节点需要的内存比工作节点少，可以为协调节点选择计算优化型机器</li></ul><p><strong>实时分析场景</strong>：</p><ul><li>总核心数：当工作数据适配内存时，Citus的性能提升与工作节点核心数成正比</li><li>工作节点RAM：最佳情况是提供足够的内存，使大部分工作集适配内存</li><li>使用<code>EXPLAIN ANALYZE</code>确定查询所需的内存</li></ul><h3 id="_8-4-查询优化" tabindex="-1">8.4 查询优化 <a class="header-anchor" href="#_8-4-查询优化" aria-label="Permalink to &quot;8.4 查询优化&quot;">​</a></h3><p>Citus通过将传入查询分解为在工作节点分片上并行运行的多个片段查询来并行化查询。由于这种并行化，可以获得反映集群中所有核心累积计算能力的性能。</p><p>Citus在规划SQL查询时使用两阶段优化器：</p><ul><li><strong>第一阶段</strong>：将SQL查询转换为可交换和关联形式，以便下推并行运行在工作节点上</li><li><strong>第二阶段</strong>：当系统将片段发送到工作节点时，工作节点运行扩展的PostgreSQL服务器，应用PostgreSQL的标准规划和执行逻辑</li></ul><p>因此，任何帮助PostgreSQL的优化也有助于Citus。PostgreSQL默认带有保守的资源设置，优化这些配置设置可以显著提高查询时间。</p><h2 id="九、最佳实践总结" tabindex="-1">九、最佳实践总结 <a class="header-anchor" href="#九、最佳实践总结" aria-label="Permalink to &quot;九、最佳实践总结&quot;">​</a></h2><h3 id="_9-1-分布列选择" tabindex="-1">9.1 分布列选择 <a class="header-anchor" href="#_9-1-分布列选择" aria-label="Permalink to &quot;9.1 分布列选择&quot;">​</a></h3><ol><li>选择<strong>最常用的连接键</strong>或<strong>大多数查询具有过滤器的列</strong>作为分布列</li><li>在多租户场景中，使用<strong>租户ID</strong>（如<code>company_id</code>、<code>account_id</code>）作为分布列</li><li>在实时分析场景中，选择<strong>高基数</strong>且<strong>均匀分布</strong>的列</li><li>避免选择值种类有限的列（如状态字段）作为分布列</li></ol><h3 id="_9-2-表类型选择" tabindex="-1">9.2 表类型选择 <a class="header-anchor" href="#_9-2-表类型选择" aria-label="Permalink to &quot;9.2 表类型选择&quot;">​</a></h3><ol><li><strong>大表</strong>：使用分布式表进行水平分片</li><li><strong>小型查找表</strong>：使用引用表在每个节点上复制</li><li><strong>管理表</strong>：使用本地表存储在协调节点上</li></ol><h3 id="_9-3-共置设计" tabindex="-1">9.3 共置设计 <a class="header-anchor" href="#_9-3-共置设计" aria-label="Permalink to &quot;9.3 共置设计&quot;">​</a></h3><ol><li>为关联查询频繁的表使用<strong>相同的分布列</strong>以实现共置</li><li>通过共置实现单节点查询，获得完整的SQL功能支持</li></ol><h3 id="_9-4-分片规划" tabindex="-1">9.4 分片规划 <a class="header-anchor" href="#_9-4-分片规划" aria-label="Permalink to &quot;9.4 分片规划&quot;">​</a></h3><ol><li>多租户场景：从32-128个分片开始</li><li>实时分析场景：每个CPU核心至少一个分片</li><li>注意连接数限制：<code>（最大并发查询数 × 分片数）</code>不超过<code>（工作节点数 × max_connections）</code></li></ol><h3 id="_9-5-运维管理" tabindex="-1">9.5 运维管理 <a class="header-anchor" href="#_9-5-运维管理" aria-label="Permalink to &quot;9.5 运维管理&quot;">​</a></h3><ol><li>Citus Community Edition 11.0+支持完全在线的分片再平衡</li><li>使用<code>citus_rebalance_start</code>函数均匀分布分片</li><li>配置复制因子以提供数据可用性</li></ol><h3 id="_9-6-版本特性" tabindex="-1">9.6 版本特性 <a class="header-anchor" href="#_9-6-版本特性" aria-label="Permalink to &quot;9.6 版本特性&quot;">​</a></h3><table tabindex="0"><thead><tr><th>版本</th><th>关键特性</th></tr></thead><tbody><tr><td>Citus 11.0</td><td>MX模式（客户端可直接连接工作节点）、在线分片再平衡</td></tr><tr><td>Citus 13.2</td><td>分片再平衡性能显著提升、延迟快速路径规划优化</td></tr></tbody></table><p>Citus作为PostgreSQL的分布式扩展，通过透明分片和并行查询实现了PostgreSQL的横向扩展。它充分利用PostgreSQL生态系统的丰富特性，同时提供分布式数据库的扩展能力，适合需要突破单机PostgreSQL性能瓶颈的场景。</p>',121)])])}const g=t(r,[["render",l]]);export{p as __pageData,g as default};
